# Keyword search: build an inverted index, then intersect postings for the query.
corpus = {'d1': 'the archive index stores every term', 'd2': 'an index speeds up keyword search', 'd3': 'archive records are stored by year'}
index = {}
for doc_id, text in corpus.items():
    for tok in text.lower().split():
        tok = tok.strip(".,;:!?()[]{}")
        if tok:
            index.setdefault(tok, set()).add(doc_id)
query = "archive index"
terms = [t.strip(".,;:!?()[]{}") for t in query.lower().split() if t.strip(".,;:!?()[]{}")]
hits = set.intersection(*[index.get(t, set()) for t in terms]) if terms else set()
print("Query:", query)
print("Matching documents:", sorted(hits) if hits else "none")
for d in sorted(hits):
    print("-", d, ":", corpus[d][:60])

